package com.josbin.phishguard.controller;
import com.josbin.phishguard.model.*; import com.josbin.phishguard.repository.*; import jakarta.servlet.http.HttpServletRequest; import org.springframework.stereotype.Controller; import org.springframework.web.bind.annotation.*;
@Controller public class TrainingController {private final TargetRepository targets;private final EventRepository events;public TrainingController(TargetRepository t,EventRepository e){targets=t;events=e;}@GetMapping("/awareness/{token}") public String awareness(@PathVariable String token,HttpServletRequest req){Target t=targets.findByTrackingToken(token).orElseThrow();events.save(new Event(t,"training_shown",req.getRemoteAddr(),ua(req)));return "training/awareness";}private String ua(HttpServletRequest r){String s=r.getHeader("User-Agent");return s==null?"":s.substring(0,Math.min(300,s.length()));}}
